package com.fintrack.khmtomnenh.quotation.controller; import com.fintrack.khmtomnenh.auth.entity.Auth; import com.fintrack.khmtomnenh.quotation.dto.QuotationDto; import com.fintrack.khmtomnenh.quotation.entity.Quotation; import com.fintrack.khmtomnenh.quotation.service.QuotationService; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.http.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/quotations") @RequiredArgsConstructor public class QuotationController {private final QuotationService s;@PostMapping @PreAuthorize("hasRole('SUPPLIER')") public ResponseEntity<Quotation> create(@Valid @RequestBody QuotationDto d,@AuthenticationPrincipal Auth a){return ResponseEntity.status(HttpStatus.CREATED).body(s.create(d,a));}@GetMapping("/mine") public List<Quotation> mine(@AuthenticationPrincipal Auth a){return a.getRole().name().equals("BUYER")?s.buyerMine(a):s.supplierMine(a);}@GetMapping("/{id}") public Quotation get(@PathVariable Long id){return s.get(id);}}
